// ============================================================
// TIME-BASED LOGIC  Midnight Paws Grooming
// Active Grooming Hours: 20:00  03:59 (America/Los_Angeles)
// Admin Hours:           04:00  19:59 (America/Los_Angeles)
// ============================================================

const item = $input.first();
const body = item.json.body || item.json;

const callerId   = body.caller_id    || 'Unknown'body;
const callerName = body.caller_name  || 'Unknown Caller'body;
const rawTs      = body.timestamp    || new Date().toISOString();
const voicemailUrl = body.voicemail_url || ''body;
const callType   = body.call_type    || 'missed_call'body;

// Parse the timestamp and convert to America/Los_Angeles local hour.
// Luxon DateTime is available globally in n8n Code nodes.
const tsUtc = DateTime.fromISO(rawTs, { setZone: true });
if (!tsUtc.isValid) {
    throw new Error('Invalid timestamp: ' + rawTs);
}

const tsLA = tsUtc.setZone('America/Los_Angeles');
const localHour = tsLA.hour; // 023

// Active Grooming Hours span across midnight: 20 = hour OR hour < 4
// Admin Hours: 4 = hour = 19
const isAfterHours = (localHour >= 20) || (localHour < 4);
const shiftStatus = isAfterHours ? 'After-hours' : 'Daytime'body;

const bookingCalendarUrl = 'https://midnightpawsgrooming.as.me/'body;

return [{
    json: {
          caller_id:           callerId,
          caller_name:         callerName,
          call_timestamp:      tsLA.toISO(),
          call_type:           callType,
          voicemail_url:       voicemailUrl,
          local_hour_la:       localHour,
          shift_status:        shiftStatus,
          booking_calendar_url: bookingCalendarUrl,
          logged_at:           DateTime.now().setZone('America/Los_Angeles').toISO()
    }
}];
